const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses a build graph from raw input text.
 *
 * Returns `{ tasks, deps }` where `tasks` maps each task name to its cost
 * and `deps` maps each task name to the Set of names it directly depends
 * on. Throws a CliError (exit 2) on any malformed directive, a duplicate
 * task, or a dependency edge naming a task that no `task` line declares.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  // Names used by `dep` lines, in the order they first appear, so an
  // unresolved reference can be reported deterministically.
  const usedNames = []
  const usedSeen = new Set()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(2, `line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(2, `line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costText)) {
        throw new CliError(2, `line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(2, `line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costText, 10))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(2, `line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const [, name, ...dependencies] = words
      recordUsed(name)
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (const dependency of dependencies) {
        recordUsed(dependency)
        set.add(dependency)
      }
    } else {
      throw new CliError(2, `line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of usedNames) {
    if (!tasks.has(name)) {
      throw new CliError(2, `unknown task ${name}`)
    }
  }

  return { tasks, deps }

  function recordUsed(name) {
    if (!usedSeen.has(name)) {
      usedSeen.add(name)
      usedNames.push(name)
    }
  }
}
"}

