{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-keSo8o/src/cycle.js","content":"import { CliError } from './errors.js'

/**
 * Depth-first searches the graph starting from each task in ascending name
 * order, walking each task's dependencies in ascending name order. Throws a
 * CliError (exit 3) describing the first cycle found, running from the
 * re-entered task through the search stack back to a repeat of that task.
 */
export function checkForCycle(graph) {
  const names = [...graph.tasks.keys()].sort()
  const state = new Map()
  const stack = []

  for (const name of names) {
    if (state.get(name) !== 'done') {
      const cycle = visit(name)
      if (cycle) {
        throw new CliError(3, `cycle: ${cycle.join(' -> ')}`)
      }
    }
  }

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)

    const dependencies = [...(graph.deps.get(name) ?? [])].sort()
    for (const dependency of dependencies) {
      const depState = state.get(dependency)
      if (depState === 'active') {
        const start = stack.indexOf(dependency)
        return [...stack.slice(start), dependency]
      }
      if (depState !== 'done') {
        const cycle = visit(dependency)
        if (cycle) return cycle
      }
    }

    stack.pop()
    state.set(name, 'done')
    return null
  }
}
"}

