{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-keSo8o/src/schedule.js","content":"/**
 * Computes, for every task, its start time, finish time and wave (depth)
 * assuming unlimited workers. A task's start is the greatest finish among
 * its dependencies (0 if it has none); its finish is start + cost. Its
 * depth is 0 with no dependencies, or one more than the greatest depth
 * among its dependencies.
 *
 * The graph is assumed acyclic (checked separately). Processes tasks in
 * topological order via Kahn's algorithm so no recursion depth is risked
 * on long chains.
 */
export function computeTimings(graph) {
  const { tasks, deps } = graph
  const info = new Map()
  const dependents = new Map()
  const remaining = new Map()

  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, set] of deps) {
    remaining.set(name, set.size)
    for (const dep of set) dependents.get(dep).push(name)
  }

  const queue = [...tasks.keys()].filter((name) => (remaining.get(name) ?? 0) === 0).sort()
  let head = 0
  while (head < queue.length) {
    const name = queue[head++]
    const depSet = deps.get(name) ?? new Set()
    let start = 0
    let depth = 0
    for (const dep of depSet) {
      const depInfo = info.get(dep)
      if (depInfo.finish > start) start = depInfo.finish
      if (depInfo.depth + 1 > depth) depth = depInfo.depth + 1
    }
    const cost = tasks.get(name)
    info.set(name, { start, finish: start + cost, depth })

    for (const dependent of dependents.get(name)) {
      const left = remaining.get(dependent) - 1
      remaining.set(dependent, left)
      if (left === 0) queue.push(dependent)
    }
  }

  let total = 0
  for (const { finish } of info.values()) {
    if (finish > total) total = finish
  }

  return { info, total }
}

/**
 * Computes each task's scheduling priority: the cost of the longest chain
 * of dependents that begins at it, counting its own cost down to a task
 * nothing depends on. Processes tasks in reverse topological order (sinks
 * first) so no recursion depth is risked on long chains.
 */
export function computePriorities(graph) {
  const { tasks, deps } = graph
  const priority = new Map()
  const remainingDependents = new Map()

  for (const name of tasks.keys()) remainingDependents.set(name, 0)
  for (const set of deps.values()) {
    for (const dep of set) remainingDependents.set(dep, remainingDependents.get(dep) + 1)
  }

  const queue = [...tasks.keys()].filter((name) => remainingDependents.get(name) === 0).sort()
  let head = 0
  while (head < queue.length) {
    const name = queue[head++]
    const dependentsOfName = []
    // Dependents of `name` are tasks whose deps set includes it; we do not
    // maintain a reverse map here, so scan lazily via deps of `name`
    // itself is not needed for this computation direction.
    priority.set(name, computePriorityFor(name))

    for (const dep of deps.get(name) ?? []) {
      const left = remainingDependents.get(dep) - 1
      remainingDependents.set(dep, left)
      if (left === 0) queue.push(dep)
    }
  }

  function computePriorityFor(name) {
    const cost = tasks.get(name)
    const dependents = dependentsOf(name)
    if (dependents.length === 0) return cost
    let best = 0
    for (const dependent of dependents) {
      const value = priority.get(dependent)
      if (value > best) best = value
    }
    return cost + best
  }

  function dependentsOf(name) {
    const result = []
    for (const [taskName, set] of deps) {
      if (set.has(name)) result.push(taskName)
    }
    return result
  }

  return priority
}

/**
 * Simulates the graph on `workerCount` workers. At each instant a free
 * worker takes the ready task with the greatest priority (ties broken by
 * ascending name), the smallest-index free worker going first. Time then
 * advances to the next instant a worker frees up. Returns the per-worker
 * run logs and the overall makespan.
 */
export function computePack(graph, workerCount) {
  const { tasks, deps } = graph
  const priority = computePriorities(graph)
  const dependentsOf = new Map()
  const inDegree = new Map()

  for (const name of tasks.keys()) dependentsOf.set(name, [])
  for (const [name, set] of deps) {
    inDegree.set(name, set.size)
    for (const dep of set) dependentsOf.get(dep).push(name)
  }

  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, current: null, log: [] }))
  const ready = [...tasks.keys()].filter((name) => (inDegree.get(name) ?? 0) === 0)
  const totalTasks = tasks.size
  let startedCount = 0
  let time = 0

  const complete = (name) => {
    for (const dependent of dependentsOf.get(name)) {
      const left = inDegree.get(dependent) - 1
      inDegree.set(dependent, left)
      if (left === 0) ready.push(dependent)
    }
  }

  while (startedCount < totalTasks) {
    // Start as many tasks as possible at the current instant.
    for (;;) {
      const freeIdx = workers.findIndex((w) => w.current === null && w.freeAt <= time)
      if (freeIdx === -1 || ready.length === 0) break

      let bestPos = 0
      for (let i = 1; i < ready.length; i++) {
        const a = ready[i]
        const b = ready[bestPos]
        if (priority.get(a) > priority.get(b) || (priority.get(a) === priority.get(b) && a < b)) {
          bestPos = i
        }
      }
      const name = ready.splice(bestPos, 1)[0]
      const cost = tasks.get(name)
      const finish = time + cost
      const worker = workers[freeIdx]
      worker.log.push({ name, start: time, finish })
      startedCount++

      if (cost === 0) {
        worker.freeAt = time
        complete(name)
      } else {
        worker.freeAt = finish
        worker.current = { name, finish }
      }
    }

    if (startedCount >= totalTasks) break

    let next = Infinity
