/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { checkForCycle } from './cycle.js'
import { computeTimings, computePack } from './schedule.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError(2, 'workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(2, USAGE)
}

async function readStdin() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks).toString('utf8')
}

function runWaves(graph) {
  const { info, total } = computeTimings(graph)
  const waveGroups = new Map()
  for (const [name, { depth }] of info) {
    if (!waveGroups.has(depth)) waveGroups.set(depth, [])
    waveGroups.get(depth).push(name)
  }
  const maxDepth = waveGroups.size === 0 ? -1 : Math.max(...waveGroups.keys())
  const lines = []
  for (let depth = 0; depth <= maxDepth; depth++) {
    const names = (waveGroups.get(depth) ?? []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((line) => line + '\n').join(''))
}

function runExplain(graph) {
  const { info, total } = computeTimings(graph)
  const names = [...info.keys()].sort()
  const lines = names.map((name) => {
    const { start, finish, depth } = info.get(name)
    return `${name} start=${start} finish=${finish} depth=${depth}`
  })
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((line) => line + '\n').join(''))
}

function runPack(graph, workerCount) {
  const { workers, makespan } = computePack(graph, workerCount)
  const lines = workers.map((worker, i) => {
    const parts = worker.log.map(({ name, start, finish }) => `${name}@${start}-${finish}`)
    return parts.length > 0 ? `worker ${i}: ${parts.join(' ')}` : `worker ${i}:`
  })
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.map((line) => line + '\n').join(''))
}

async function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = await readStdin()
  const graph = parseGraph(input)
  checkForCycle(graph)

  if (mode === 'waves') runWaves(graph)
  else if (mode === 'explain') runExplain(graph)
  else runPack(graph, workers)
}

main().catch((err) => {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.code)
  }
  throw err
})
"}

