  const maxDepth = waveGroups.size === 0 ? -1 : Math.max(...waveGroups.keys())
  const lines = []
  for (let depth = 0; depth <= maxDepth; depth++) {
    const names = (waveGroups.get(depth) ?? []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((line) => line + '\n').join(''))
}

function runExplain(graph) {
  const { info, total } = computeTimings(graph)
  const names = [...info.keys()].sort()
  const lines = names.map((name) => {
    const { start, finish, depth } = info.get(name)
    return `${name} start=${start} finish=${finish} depth=${depth}`
  })
  lines.push(`total ${total}`)
  process.stdout.write(lines.map((line) => line + '\n').join(''))
}

function runPack(graph, workerCount) {
  const { workers, makespan } = computePack(graph, workerCount)
  const lines = workers.map((worker, i) => {
    const parts = worker.log.map(({ name, start, finish }) => `${name}@${start}-${finish}`)
    return parts.length > 0 ? `worker ${i}: ${parts.join(' ')}` : `worker ${i}:`
  })
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.map((line) => line + '\n').join(''))
}

async function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = await readStdin()
  const graph = parseGraph(input)
  checkForCycle(graph)

  if (mode === 'waves') runWaves(graph)
  else if (mode === 'explain') runExplain(graph)
  else runPack(graph, workers)
}

main().catch((err) => {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.code)
  }
  throw err
})
